from __future__ import annotations
from pathlib import Path
import re,sys
root=Path(sys.argv[1] if len(sys.argv)>1 else 'v1.1/base').resolve()

def one(s,old,new,label):
    if old not in s:raise SystemExit(f'anchor missing: {label}')
    return s.replace(old,new,1)

def patch_server(s):
    s=one(s,'import agents, analysis, components, core, jarvis_bridge, software','import agents, analysis, core, jarvis_bridge, software\nimport component_registry as components\nimport physical_components','server imports')
    s=one(s,'class ComponentSearchBody(BaseModel): query:str=""; category:str|None=None; constraints:dict[str,Any]=Field(default_factory=dict); weights:dict[str,float]=Field(default_factory=dict); limit:int=20; include_infeasible:bool=True','class ComponentSearchBody(BaseModel): query:str=""; category:str|None=None; constraints:dict[str,Any]=Field(default_factory=dict); weights:dict[str,float]=Field(default_factory=dict); limit:int=20; include_infeasible:bool=True; min_trust:int=0; min_geometry_fidelity:str|None=None\nclass ComponentSelectBody(BaseModel): query:str=""; category:str|None=None; requirements:dict[str,Any]=Field(default_factory=dict); limit:int=8\nclass MateBody(BaseModel): source_id:str; source_interface:str; target_id:str; target_interface:str; gap_mm:float=0\nclass ConnectBody(BaseModel): a_id:str; a_interface:str; b_id:str; b_interface:str; kind:str="auto"','component models')
    start=s.index('@app.get("/api/components")')
    end=s.index('@app.get("/api/code/{object_id}")',start)
    block='''@app.get("/api/components")\ndef comp_list(category:str|None=None):\n    stats=components.registry_stats();return {"categories":components.categories(),"total":stats["total"],"stats":stats,"results":components.all_components(category)}\n@app.get("/api/components/schema")\ndef comp_schema():return components.component_schema()\n@app.get("/api/components/stats")\ndef comp_stats():return components.registry_stats()\n@app.get("/api/components/providers")\ndef comp_providers():return components.provider_status()\n@app.post("/api/components/search")\ndef comp_search(body:ComponentSearchBody):return components.search_components(body.query,body.category,body.constraints,body.weights,body.limit,body.include_infeasible,body.min_trust,body.min_geometry_fidelity)\n@app.post("/api/components/select")\ndef comp_select(body:ComponentSelectBody):return components.select_component(body.requirements,category=body.category,query=body.query,limit=body.limit)\n@app.post("/api/components/import")\ndef comp_import(payload:dict[str,Any]|list[dict[str,Any]]=Body(...)):\n    try:return components.import_components(payload)\n    except Exception as e:fail(e)\n@app.post("/api/components/import-pack")\nasync def comp_import_pack(file:UploadFile=File(...)):\n    try:return components.import_catalog_pack_bytes(file.filename or "catalog.json",await file.read())\n    except Exception as e:fail(e)\n@app.get("/api/components/{component_id}")\ndef comp_get(component_id:str):\n    try:return components.component_by_id(component_id)\n    except KeyError as e:fail(e,404)\n@app.get("/api/components/{component_id}/compatible/{other_id}")\ndef comp_compatible(component_id:str,other_id:str):\n    try:return {"a":component_id,"b":other_id,"interfaces":components.compatible_interfaces(component_id,other_id)}\n    except KeyError as e:fail(e,404)\n@app.post("/api/components/{component_id}/asset")\nasync def comp_asset(component_id:str,file:UploadFile=File(...),role:str="geometry",source_kind:str="user_supplied",source_url:str|None=None):\n    try:return components.register_asset_bytes(component_id,file.filename or "asset.step",await file.read(),role=role,source_kind=source_kind,source_url=source_url)\n    except KeyError as e:fail(e,404)\n    except Exception as e:fail(e)\n@app.post("/api/components/add/{component_id}")\ndef comp_add(component_id:str):\n    try:return core.execute("add_component",{"component_id":component_id},"human",f"add purchased component {component_id}")\n    except KeyError as e:fail(e,404)\n    except Exception as e:fail(e)\n@app.post("/api/components/sync/{object_id}")\ndef comp_sync(object_id:str):\n    try:return core.execute("sync_component",{"id":object_id},"human","explicitly sync component registry snapshot")\n    except KeyError as e:fail(e,404)\n    except Exception as e:fail(e)\n@app.post("/api/assembly/mate")\ndef assembly_mate(body:MateBody):\n    try:return core.execute("mate_components",body.model_dump(),"human","mate real-world component interfaces")\n    except KeyError as e:fail(e,404)\n    except Exception as e:fail(e)\n@app.post("/api/connections")\ndef connection_add(body:ConnectBody):\n    try:return core.execute("connect_interfaces",body.model_dump(),"human","connect component interfaces")\n    except KeyError as e:fail(e,404)\n    except Exception as e:fail(e)\n@app.delete("/api/connections/{connection_id}")\ndef connection_delete(connection_id:str):\n    try:return core.execute("disconnect",{"id":connection_id},"human","remove interface connection")\n    except KeyError as e:fail(e,404)\n@app.get("/api/reality-check")\ndef reality_check():return core.reality_check()\n\n'''
    s=s[:start]+block+s[end:]
    s=one(s,'def capabilities():return analysis.system_capabilities()|{"ollama":agents.status(),"component_count":len(components.REGISTRY)}','def capabilities():return analysis.system_capabilities()|{"ollama":agents.status(),"component_count":components.registry_stats()["total"],"component_registry":components.registry_stats()}','capabilities')
    s=one(s,'def j_component(body:JarvisComponentBody,_:None=__import__(\'fastapi\').Depends(require_jarvis)):return components.search_components(body.query,body.category,body.constraints,body.weights,10,True)','def j_component(body:JarvisComponentBody,_:None=__import__(\'fastapi\').Depends(require_jarvis)):return components.select_component(body.constraints,category=body.category,query=body.query,limit=10)','jarvis select')
    old='''def j_reality(_:None=__import__('fastapi').Depends(require_jarvis)):\n    risks=[]\n    stale=sum(1 for s in core.PROJECT.get("simulations",[]) if s.get("stale"));\n    if stale:risks.append({"severity":"warning","message":f"{stale} prior analyses are stale after design changes."})\n    if not any(d.get("physical_verified") for d in core.DESIGNS.values()):risks.append({"severity":"info","message":"No design branch is marked physically verified."})\n    return {"risks":risks,"stale_simulations":stale,"trust":"Screening analyses do not replace physical verification."}\n'''
    new='''def j_reality(_:None=__import__('fastapi').Depends(require_jarvis)):\n    scan=core.reality_check();risks=list(scan.get("risks",[]));stale=sum(1 for s in core.PROJECT.get("simulations",[]) if s.get("stale"))\n    if stale:risks.append({"severity":"warning","code":"stale_analysis","message":f"{stale} prior analyses are stale after design changes."})\n    if not any(d.get("physical_verified") for d in core.DESIGNS.values()):risks.append({"severity":"info","code":"no_physical_verification","message":"No design branch is marked physically verified."})\n    return {**scan,"risks":risks,"stale_simulations":stale,"trust":"Component provenance and screening analyses do not replace physical verification."}\n'''
    s=one(s,old,new,'jarvis reality')
    old='''@app.get("/api/tools")\ndef tools():return {"principle":"Human UI, local AI and Jarvis call the same deterministic typed operations; UI state is never authoritative.","operations":["add","update","transform","delete","add_feature","delete_feature","add_load","add_constraint","set_requirement","add_bom_item","add_note","code_write","code_delete","code_rename"],"analysis":["cantilever screening","reduced-order structural preview","modal screening","thermal screening","parameter optimization","manufacturing screening"],"openapi":"/openapi.json","docs":"/docs"}\n'''
    new='''@app.get("/api/tools")\ndef tools():return {"principle":"Human UI, local AI and Jarvis call the same deterministic typed operations; UI state is never authoritative.","operations":["add","add_component","replace_component","sync_component","update","transform","mate_components","connect_interfaces","disconnect","delete","add_feature","delete_feature","add_load","add_constraint","set_requirement","add_bom_item","add_note","code_write","code_delete","code_rename"],"component_registry":{"schema":"/api/components/schema","stats":"/api/components/stats","search":"POST /api/components/search","select":"POST /api/components/select","import_pack":"POST /api/components/import-pack","reality_check":"/api/reality-check"},"analysis":["cantilever screening","reduced-order structural preview","modal screening","thermal screening","parameter optimization","manufacturing screening"],"openapi":"/openapi.json","docs":"/docs"}\n'''
    s=one(s,old,new,'tools')
    return s

def patch_agents(s):
    s=one(s,'OPS=["add","update","transform","delete","add_feature","delete_feature","add_load","add_constraint","set_requirement","add_bom_item","add_note","code_write","code_delete","code_rename","project_name","settings"]','OPS=["add","add_component","replace_component","sync_component","update","transform","mate_components","connect_interfaces","disconnect","delete","add_feature","delete_feature","add_load","add_constraint","set_requirement","add_bom_item","add_note","code_write","code_delete","code_rename","project_name","settings"]','agent ops')
    old='''    summary={"name":p.get("name"),"objects":[{"id":o.get("id"),"name":o.get("name"),"kind":o.get("kind"),"params":o.get("params"),"material":o.get("material"),"component_ref":o.get("component_ref")} for o in p.get("objects",[])],"requirements":p.get("requirements",[])[:20]}\n    system=f"""You are ForgeCAD's local mechanical/electromechanical design planner. Return JSON only: {{\\"summary\\":\\"...\\",\\"commands\\":[{{\\"op\\":\\"...\\",\\"args\\":{{...}}}}],\\"checks\\":[\\"...\\"]}}. Allowed operations: {OPS}. Never invent object IDs; use IDs from the supplied project. Prefer explicit dimensions in mm. If a request cannot be made safely with the typed operations, return no commands and explain in summary. Do not claim a screening analysis proves a safety-critical design."""\n'''
    new='''    import component_registry\n    summary={"name":p.get("name"),"objects":[{"id":o.get("id"),"name":o.get("name"),"kind":o.get("kind"),"params":o.get("params"),"material":o.get("material"),"component_ref":o.get("component_ref"),"interfaces":[i.get("id") for i in o.get("interfaces",[])]} for o in p.get("objects",[])],"requirements":p.get("requirements",[])[:20],"connections":p.get("connections",[])[:30]}\n    candidates=[];low=text.lower();category_map={"stepper":"stepper_motor","motor":"stepper_motor","servo":"servo","solenoid":"solenoid","bearing":"bearing","fan":"fan","raspberry pi":"compute","arduino":"microcontroller","microcontroller":"microcontroller","sensor":"sensor","battery":"battery","fastener":"fastener","screw":"fastener","linear rail":"linear_motion","buck":"power"}\n    seen=set()\n    for token,cat in category_map.items():\n        if token in low:\n            for c in component_registry.search_components("",cat,limit=8,include_infeasible=True)["results"]:\n                if c["id"] not in seen:candidates.append({"id":c["id"],"name":c["name"],"category":c["category"],"specs":c.get("specs",{}),"interfaces":[i.get("id") for i in c.get("interfaces",[])],"geometry_fidelity":c.get("geometry",{}).get("fidelity"),"trust_score":c.get("trust_score")});seen.add(c["id"])\n    candidates=candidates[:24]\n    system=f"""You are ForgeCAD's local mechanical/electromechanical design planner. Return JSON only: {{\\"summary\\":\\"...\\",\\"commands\\":[{{\\"op\\":\\"...\\",\\"args\\":{{...}}}}],\\"checks\\":[\\"...\\"]}}. Allowed operations: {OPS}. Never invent object IDs or component IDs. For commercially purchasable hardware, strongly prefer add_component with an exact component_id from COMPONENT CANDIDATES instead of drawing a generic box. Use mate_components only with exact object IDs and interface IDs supplied in project state. Use connect_interfaces for electrical/logical connections. Preserve vendor geometry and component snapshots; do not edit a purchased component's dimensions as if it were fabricated material. Prefer explicit dimensions in mm for custom parts. If no supplied component candidate is adequate, return no purchase command and say what catalog data is missing. Treat low-trust or low-fidelity data as a verification requirement. Do not claim a screening analysis proves a safety-critical design."""\n    summary["component_candidates"]=candidates\n'''
    s=one(s,old,new,'agent component candidates')
    return s

for name,fn in [('server.py',patch_server),('agents.py',patch_agents)]:
    p=root/name;s=p.read_text(encoding='utf-8');n=fn(s);p.write_text(n,encoding='utf-8');print('patched',name)
